    choices: [{"id": "a", "text": "Lymphatic filariasis (elephantiasis)"}, {"id": "b", "text": "Reactive arthritis (Reiter's syndrome)"}, {"id": "c", "text": "Hodgkin's lymphoma"}, {"id": "d", "text": "Massive splenomegaly"}],
